package com.imth3keeza0.ultimateslayer;

import java.util.Map;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/** Session-only immutable progression copy. Never persisted with bank items. */
public final class AccountContext
{
    public static final AccountContext UNKNOWN = new AccountContext(Map.of(), Map.of());
    public final int spellbook;
    private final Map<Skill, Integer> levels;
    private final Map<Quest, Boolean> quests;
    private final Map<Skill, Integer> boosted;
    public AccountContext(Map<Skill, Integer> levels, Map<Quest, Boolean> quests)
    { this(levels, quests, -1); }
    public AccountContext(Map<Skill, Integer> levels, Map<Quest, Boolean> quests, int spellbook)
    { this(levels, quests, spellbook, levels); }
    public AccountContext(Map<Skill, Integer> levels, Map<Quest, Boolean> quests, int spellbook, Map<Skill, Integer> boosted)
    { this.levels = Map.copyOf(levels); this.quests = Map.copyOf(quests); this.spellbook = spellbook; this.boosted = Map.copyOf(boosted); }
    public int boostedLevel(Skill skill) { return boosted.getOrDefault(skill, level(skill)); }
    public boolean sameAs(AccountContext other) { return other != null && levels.equals(other.levels) && boosted.equals(other.boosted) && quests.equals(other.quests) && spellbook == other.spellbook; }
    public int signature() { return java.util.Objects.hash(levels, quests, boosted, spellbook); }
    public int level(Skill skill) { return levels.getOrDefault(skill, -1); }
    public Boolean completed(Quest quest) { return quests.get(quest); }
    public String levelStatus(Skill skill, int needed)
    {
        int actual = level(skill);
        return skill.getName() + " " + needed + ": " + (actual < 0 ? "unknown" : actual >= needed ? "base level met (" + actual + ")" : "base level too low (" + actual + "); boosts not evaluated");
    }
    public String questStatus(Quest quest)
    { Boolean done = completed(quest); return quest.getName() + ": " + (done == null ? "unknown" : done ? "complete" : "not complete"); }
}

package com.imth3keeza0.ultimateslayer;

import java.util.Locale;
import java.util.Map;

/** Explicit supported weapon/ammo families. Unknown pairings never become matches. */
public final class AmmoCompatibility
{
    private AmmoCompatibility() {}
    public static boolean matches(OwnedGearPlanner.Gear weapon, OwnedGearPlanner.Gear ammo)
    {
        String w = clean(weapon.name), a = clean(ammo.name);
        if (w.startsWith("karil's crossbow")) { return a.equals("bolt rack"); }
        if (w.equals("dorgeshuun crossbow")) { return a.equals("bone bolts"); }
        if (w.contains("ballista")) { return a.contains("javelin"); }
        if (w.equals("hunters' sunlight crossbow")) { return a.equals("sunlight antler bolts") || a.equals("moonlight antler bolts"); }
        if (w.endsWith("crossbow"))
        {
            if (!a.contains("bolts") || a.contains("antler") || a.equals("bone bolts") || a.equals("bolt rack")) { return false; }
            int max = w.equals("rune crossbow") ? 7 : w.equals("adamant crossbow") ? 6 : w.equals("mithril crossbow") ? 5
                : w.equals("steel crossbow") ? 4 : w.equals("iron crossbow") ? 3 : w.equals("blurite crossbow") ? 2
                : w.equals("bronze crossbow") || w.equals("crossbow") ? 1
                : w.equals("dragon crossbow") || w.equals("armadyl crossbow") || w.equals("dragon hunter crossbow") || w.equals("zaryte crossbow") ? 8 : 0;
            int tier = boltTier(a); return tier > 0 && tier <= max;
        }
        if (!a.contains("arrow") || a.contains("ogre") || a.contains("brutal") || a.contains("ice") || a.contains("fire")) { return false; }
        int tier = a.startsWith("broad") ? 5 : metalTier(a);
        int max = 0;
        if (w.equals("shortbow") || w.equals("longbow")) { max = 2; }
        else if (w.startsWith("oak ")) { max = 3; } else if (w.startsWith("willow ")) { max = 4; }
        else if (w.startsWith("maple ")) { max = 5; } else if (w.startsWith("yew ")) { max = 6; }
        else if (w.startsWith("magic shortbow") || w.startsWith("magic longbow") || w.equals("venator bow")) { max = 7; }
        else if (w.equals("twisted bow") || w.equals("dark bow") || w.equals("3rd age bow")) { max = 8; }
        return tier > 0 && tier <= max;
    }
    private static String clean(String name) { return name.toLowerCase(Locale.ROOT).trim().replaceAll("\\(p\\+*\\)", "").trim(); }
    private static int metalTier(String name)
    {
        String[] metals = {"bronze", "iron", "steel", "mithril", "adamant", "rune", "amethyst", "dragon"};
        for (int i = 0; i < metals.length; i++) { if (name.startsWith(metals[i] + " ")) { return i + 1; } } return 0;
    }
    private static int boltTier(String name)
    {
        if (name.contains("dragon bolts")) { return 8; }
        if (name.startsWith("opal")) { return 1; } if (name.startsWith("jade")) { return 2; }
        if (name.startsWith("pearl")) { return 3; } if (name.startsWith("topaz")) { return 4; }
        if (name.startsWith("sapphire") || name.startsWith("emerald")) { return 5; }
        if (name.startsWith("ruby") || name.startsWith("diamond")) { return 6; }
        if (name.startsWith("dragonstone") || name.startsWith("onyx") || name.startsWith("broad") || name.startsWith("amethyst broad")) { return 7; }
        String[] metals = {"bronze", "blurite", "iron", "steel", "mithril", "adamant", "runite", "dragon"};
        for (int i = 0; i < metals.length; i++) { if (name.startsWith(metals[i] + " ")) { return i + 1; } }
        return name.startsWith("rune ") ? 7 : 0;
    }
    public static String explain(OwnedGearPlanner.Gear weapon, boolean found)
    {
        String n = clean(weapon.name);
        if (n.contains("blowpipe")) { return "Blowpipe darts/scales are internal: inspect charges manually."; }
        if (n.contains("crystal bow") || n.contains("faerdhinen") || weapon.category.equals("Thrown") || weapon.category.equals("Chinchompas"))
        { return "No separate arrows/bolts suggested; verify ammunition or internal charges."; }
        return found ? "Compatible owned ammo selected; quantities and special effects are not optimised." : "No supported compatible ammo observed. Check weapon/ammunition before leaving.";
    }
}

package com.imth3keeza0.ultimateslayer;

/** One claim per genuine bank opening. No client reads or timers. */
public final class BankSessionGate
{
    private boolean open;
    private boolean claimed;
    private long session;

    public void opened()
    {
        if (!open) { open = true; claimed = false; ++session; }
    }

    public void closed() { open = false; claimed = false; ++session; }
    public void suppressCurrentOpening() { if (open) { claimed = true; } }
    public long session() { return session; }
    public boolean pending() { return open && !claimed; }
    public boolean claim(long expected)
    {
        if (!pending() || expected != session) { return false; }
        claimed = true;
        return true;
    }
}

package com.imth3keeza0.ultimateslayer;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/** Raw IDs retain charged, degraded and other functional variants. */
public final class BankSnapshot
{
    public final long capturedAt;
    public final Map<Integer, Long> bank;
    public final Map<Integer, Long> inventory;
    public final Map<Integer, Long> equipment;

    public BankSnapshot(long capturedAt, Map<Integer, Long> bank, Map<Integer, Long> inventory, Map<Integer, Long> equipment)
    {
        if (capturedAt <= 0 || capturedAt > System.currentTimeMillis() + 60_000) { throw new IllegalArgumentException("Invalid capture time"); }
        this.capturedAt = capturedAt;
        this.bank = checkedCopy(bank);
        this.inventory = checkedCopy(inventory);
        this.equipment = checkedCopy(equipment);
    }

    private static Map<Integer, Long> checkedCopy(Map<Integer, Long> source)
    {
        if (source.size() > 2000) { throw new IllegalArgumentException("Too many entries"); }
        Map<Integer, Long> copy = new LinkedHashMap<>();
        source.forEach((id, count) -> {
            if (id == null || count == null || id <= 0 || count <= 0 || count > Integer.MAX_VALUE * 2000L)
            { throw new IllegalArgumentException("Invalid item entry"); }
            copy.put(id, count);
        });
        return Collections.unmodifiableMap(copy);
    }
}

package com.imth3keeza0.ultimateslayer;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Consumer;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Filepath;

/** Personal-bank capture only. No input, PIN, login widget, or HTTP access. */
public final class BankSnapshotController
{
    public interface Directory { Filepath get() throws IOException; }
    private final Client client;
    private final ClientThread clientThread;
    private final ConfigManager config;
    private final Directory directory;
    private final Consumer<String> status;
    private final BankSessionGate gate = new BankSessionGate();
    private volatile long revision;
    private volatile boolean running;
    private String character;
    private boolean scheduled;
    private BankSnapshot snapshot;
    private Consumer<BankSnapshot> snapshotListener = ignored -> {};
    public void setSnapshotListener(Consumer<BankSnapshot> listener) { snapshotListener = listener; }
    public BankSnapshot getSnapshot() { return snapshot; } // Client thread only.

    public BankSnapshotController(Client client, ClientThread clientThread, ConfigManager config,
                                  Directory directory, Consumer<String> status)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
        this.directory = directory;
        this.status = status;
    }

    public void start()
    {
        running = true;
        clientThread.invokeLater(() -> {
            if (!running) { return; }
            ensureCharacter();
            // Enabling while already banking does not create a new bank opening.
            if (bankVisible()) { gate.opened(); gate.suppressCurrentOpening(); }
        });
    }

    public void stop()
    {
        running = false;
        ++revision;
        gate.closed();
        character = null;
        snapshot = null;
        snapshotListener.accept(null);
        // Drain explicit deletions even when disabled; stale writes check running/revision.
        // Shared IO queue survives disable/re-enable so a new load cannot overtake a clear.
    }

    public void accountTransition()
    {
        if (!running) { return; }
        ++revision;
        character = null;
        snapshot = null;
        snapshotListener.accept(null);
        gate.closed();
        status.accept("Log in and open your bank.");
    }

    public void loggedIn() { if (running) { ensureCharacter(); } }

    private boolean ensureCharacter()
    {
        if (!running || client.getGameState() != GameState.LOGGED_IN) { return false; }
        String profile = config.getRSProfileKey();
        if (profile == null || profile.isEmpty()) { return false; }
        String key = hash(profile);
        if (key.equals(character)) { return true; }
        character = key;
        snapshot = null;
        snapshotListener.accept(null);
        final long token = ++revision;
        status.accept("Loading this character's local snapshot…");
        submit(() -> {
            try
            {
                BankSnapshot loaded = new BankSnapshotStore(directory.get()).load(key);
                complete(token, () -> { snapshot = loaded; snapshotListener.accept(loaded); showSnapshot(loaded == null ? "Open your bank to capture items." : "Saved locally"); });
            }
            catch (IOException | RuntimeException e) { complete(token, () -> status.accept("Saved data unavailable. Reopen the bank to replace it.")); }
        });
        return true;
    }

    public void opened()
    {
        if (!running) { return; }
        ensureCharacter();
        gate.opened();
    }

    public void closed() { if (running) { gate.closed(); } }

    public void bankBuilt()
    {
        if (!running || !gate.pending() || scheduled) { return; }
        final long opening = gate.session();
        scheduled = true;
        clientThread.invokeAtTickEnd(() -> {
            scheduled = false;
            if (!running || !gate.pending() || opening != gate.session() || !bankVisible() || !ensureCharacter()) { return; }
            if (!gate.claim(opening)) { return; }
            // A visible health bar is a conservative recent-combat guard.
            if (client.getLocalPlayer() == null || client.getLocalPlayer().getHealthRatio() >= 0
                || client.getLocalPlayer().getInteracting() instanceof net.runelite.api.Player
                || (client.getLocalPlayer().getInteracting() instanceof NPC
                    && ((NPC) client.getLocalPlayer().getInteracting()).getCombatLevel() > 0))
            {
                status.accept("Capture skipped after recent combat. Reopen the bank once safe.");
                return;
            }
            ItemContainer bank = client.getItemContainer(InventoryID.BANK);
            if (bank == null)
            {
                status.accept("Bank contents were not ready. Close and reopen the bank.");
                return;
            }
            Map<Integer, Long> bankItems = copy(bank);
            Map<Integer, Long> carried = copy(client.getItemContainer(InventoryID.INVENTORY));
            Map<Integer, Long> worn = copy(client.getItemContainer(InventoryID.EQUIPMENT));
            snapshot = new BankSnapshot(System.currentTimeMillis(), bankItems, carried, worn);
            snapshotListener.accept(snapshot);
            final BankSnapshot captured = snapshot;
            final String key = character;
            final long token = ++revision; // Prevent an older disk load replacing this capture.
            showSnapshot("Saving locally…");
            submit(() -> {
                if (!running || token != revision) { return; }
                try
                {
                    new BankSnapshotStore(directory.get()).save(key, captured);
                    complete(token, () -> showSnapshot("Saved locally"));
                }
                catch (IOException | RuntimeException e) { complete(token, () -> showSnapshot("Local save failed; current session only")); }
            });
        });
    }

    private boolean bankVisible()
    {
        Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
        return bank != null && !bank.isHidden();
    }

    private Map<Integer, Long> copy(ItemContainer container)
    {
        Map<Integer, Long> result = new LinkedHashMap<>();
        if (container == null) { return result; }
        Item[] entries = container.getItems();
        if (entries.length > 2000) { throw new IllegalArgumentException("Unexpected container size"); }
        for (Item item : entries)
        {
            if (item != null && item.getId() > 0 && item.getId() != ItemID.BANK_FILLER && item.getQuantity() > 0)
            {
                result.merge(item.getId(), (long) item.getQuantity(), Long::sum);
            }
        }
        return result;
    }

    public void clear()
    {
        clientThread.invokeLater(() -> {
            if (!running || !ensureCharacter()) { return; }
            final String key = character;
            final long token = ++revision;
            snapshot = null;
            snapshotListener.accept(null);
            gate.suppressCurrentOpening();
            status.accept("Clearing this character's saved items…");
            // Serial IO ensures an in-flight save finishes before this deletion.
            submit(() -> {
                try
                {
                    new BankSnapshotStore(directory.get()).clear(key);
                    complete(token, () -> status.accept("Saved items cleared. Close and reopen the bank to capture again."));
                }
                catch (IOException | RuntimeException e) { complete(token, () -> status.accept("Could not clear saved data. Please try again.")); }
            });
        });
    }

    private void showSnapshot(String note)
    {
        if (snapshot == null) { status.accept(note); return; }
        String time = DateTimeFormatter.ofPattern("dd MMM HH:mm:ss").withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(snapshot.capturedAt));
        status.accept(snapshot.bank.size() + " bank item types · " + time + ". " + note + ". Changes appear next opening.");
    }

    private void complete(long token, Runnable action)
    {
        clientThread.invokeLater(() -> { if (running && token == revision) { action.run(); } });
    }

    private void submit(Runnable action)
    {
        if (!LocalSnapshotIo.submit(action) && running) { status.accept("Local storage busy. Please try again."); }
    }

    private static String hash(String profile)
    {
        try
        {
            byte[] bytes = MessageDigest.getInstance("SHA-256").digest(profile.getBytes(StandardCharsets.UTF_8));
            StringBuilder result = new StringBuilder();
            for (byte value : bytes) { result.append(String.format("%02x", value & 255)); }
            return result.toString();
        }
        catch (NoSuchAlgorithmException e) { throw new IllegalStateException(e); }
    }
}

package com.imth3keeza0.ultimateslayer;

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.client.util.Filepath;

/** Called exclusively on the plugin's serial IO worker. No synced config. */
public final class BankSnapshotStore
{
    private final Filepath root;
    public BankSnapshotStore(Filepath root) { this.root = root; }

    private Filepath file(String key)
    {
        if (!key.matches("[a-f0-9]{64}")) { throw new IllegalArgumentException("Invalid character key"); }
        return root.joinSegment(key + ".snapshot");
    }

    public BankSnapshot load(String key) throws IOException
    {
        Filepath file = file(key);
        if (!file.exists()) { return null; }
        if (file.size() > 262_144) { throw new IOException("Snapshot too large"); }
        try (BufferedReader reader = file.openBufferedReader())
        {
            return decode(reader);
        }
    }

    static BankSnapshot decode(BufferedReader reader) throws IOException
    {
        try
        {
            if (!"ultimate-slayer-bank-v1".equals(reader.readLine())) { throw new IOException("Unknown schema"); }
            long captured = Long.parseLong(reader.readLine());
            Map<Integer, Long> bank = new LinkedHashMap<>();
            Map<Integer, Long> inventory = new LinkedHashMap<>();
            Map<Integer, Long> equipment = new LinkedHashMap<>();
            String line;
            int lines = 0;
            while ((line = reader.readLine()) != null)
            {
                if (++lines > 2100) { throw new IOException("Too many entries"); }
                String[] fields = line.split("\t", -1);
                if (fields.length != 3) { throw new IOException("Invalid entry"); }
                Map<Integer, Long> target;
                switch (fields[0])
                {
                    case "B": target = bank; break;
                    case "I": target = inventory; break;
                    case "E": target = equipment; break;
                    default: throw new IOException("Invalid container");
                }
                if (target.put(Integer.parseInt(fields[1]), Long.parseLong(fields[2])) != null)
                { throw new IOException("Duplicate entry"); }
            }
            return new BankSnapshot(captured, bank, inventory, equipment);
        }
        catch (IllegalArgumentException e) { throw new IOException("Invalid snapshot", e); }
    }

    public void save(String key, BankSnapshot snapshot) throws IOException
    {
        root.createDirectories();
        Filepath temporary = root.createTempFile("bank-", ".tmp");
        try
        {
            temporary.write(encode(snapshot));
            try { temporary.moveTo(file(key), StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING); }
            catch (AtomicMoveNotSupportedException e) { temporary.moveTo(file(key), StandardCopyOption.REPLACE_EXISTING); }
        }
        finally { temporary.deleteIfExists(); }
    }

    static String encode(BankSnapshot snapshot)
    {
        StringBuilder data = new StringBuilder("ultimate-slayer-bank-v1\n").append(snapshot.capturedAt).append('\n');
        append(data, "B", snapshot.bank);
        append(data, "I", snapshot.inventory);
        append(data, "E", snapshot.equipment);
        return data.toString();
    }

    private static void append(StringBuilder data, String container, Map<Integer, Long> entries)
    {
        entries.forEach((id, count) -> data.append(container).append('\t').append(id).append('\t').append(count).append('\n'));
    }

    public void clear(String key) throws IOException { file(key).deleteIfExists(); }
}

package com.imth3keeza0.ultimateslayer;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Skill;

/** Original implementation of documented ordinary PvM attack equations. No game actions. */
public final class CombatCalculator
{
    private CombatCalculator() {}
    public enum PrayerBoost { NONE, PIETY, RIGOUR, AUGURY }
    public static final class Mode
    {
        public final String style, stance;
        public Mode(String style, String stance) { this.style = style; this.stance = stance; }
        @Override public String toString() { return style + " / " + stance; }
    }
    public static final class Inputs
    {
        public final AccountContext account;
        public final ReferenceCatalog.Monster target;
        public final Mode mode;
        public final String spell, task;
        public final boolean onTask, charged, boosted;
        public final PrayerBoost prayer;
        public final TaskReferenceData.Location location;
        public final TaskReferenceData.Exemption exemption;
        public Inputs(AccountContext account, ReferenceCatalog.Monster target, Mode mode, String spell, String task,
                      TaskReferenceData.Location location, TaskReferenceData.Exemption exemption, boolean onTask,
                      boolean charged, boolean boosted, PrayerBoost prayer)
        {
            this.account = account; this.target = target; this.mode = mode; this.spell = spell; this.task = task;
            this.location = location; this.exemption = exemption; this.onTask = onTask; this.charged = charged; this.boosted = boosted; this.prayer = prayer;
        }
        public Inputs withMode(Mode next)
        { return new Inputs(account, target, next, spell, task, location, exemption, onTask, charged, boosted, prayer); }
        int level(Skill skill) { return boosted ? account.boostedLevel(skill) : account.level(skill); }
    }
    public static final class Result
    {
        public final boolean available;
        public final String reason;
        public final double dps, accuracy, meanHit;
        public final int maxHit, ticks;
        public final long attackRoll, defenceRoll;
        public final List<String> effects, warnings;
        private Result(String reason, double dps, double accuracy, double meanHit, int maxHit, int ticks, long attackRoll, long defenceRoll, List<String> effects, List<String> warnings)
        {
            available = reason.isEmpty(); this.reason = reason; this.dps = dps; this.accuracy = accuracy; this.meanHit = meanHit;
            this.maxHit = maxHit; this.ticks = ticks; this.attackRoll = attackRoll; this.defenceRoll = defenceRoll;
            this.effects = List.copyOf(effects); this.warnings = List.copyOf(warnings);
        }
        static Result unavailable(String reason) { return new Result(reason, 0, 0, 0, 0, 0, 0, 0, List.of(), List.of()); }
        public String summary() { return available ? String.format(Locale.ROOT, "%.2f normal-attack DPS · %.1f%% hit · max %d · %d ticks", dps, accuracy * 100, maxHit, ticks) : reason; }
    }
    public static double hitChance(long attack, long defence)
    {
        if (attack < 0 || defence < 0) { throw new IllegalArgumentException("Negative-roll mechanics are outside this model"); }
        return attack > defence ? 1.0 - (defence + 2.0) / (2.0 * (attack + 1.0)) : attack / (2.0 * (defence + 1.0));
    }
    /** Successful zero rolls become one; misses are handled separately by hitChance. */
    public static double normalMean(int maximum) { return maximum < 1 ? 0 : maximum / 2.0 + 1.0 / (maximum + 1.0); }
    static String name(OwnedGearPlanner.Gear item) { return item == null ? "" : item.name.toLowerCase(Locale.ROOT); }
    static boolean chargedItem(OwnedGearPlanner.Gear item)
    {
        String n = name(item);
        return n.matches(".*(trident|sanguinesti|warped sceptre|crystal|faerdhinen|saeldor|tentacle|barrows|ahrim|dharok|guthan|karil|torag|verac).*" );
    }
    static boolean poweredWeapon(OwnedGearPlanner.Gear weapon)
    { String n = name(weapon); return n.contains("trident") || n.contains("sanguinesti") || n.equals("warped sceptre"); }
    static String blockedItem(OwnedGearPlanner.Gear gear, Inputs input)
    {
        String n = name(gear); ReferenceCatalog.Equipment ref = ReferenceCatalog.get().equipment.get(gear.id);
        if (n.matches(".*(uncharged|broken|inactive|\\(empty\\)).*") || (ref != null && ref.version.toLowerCase(Locale.ROOT).matches(".*(inactive|uncharged|broken|empty).*"))) { return "Known inactive item: " + gear.name; }
        String rejection = EquipmentEligibility.rejection(gear, input.account);
        if (rejection != null && !EquipmentEligibility.unverified(rejection)) { return gear.name + ": " + rejection; }
        if (chargedItem(gear) && !input.charged) { return "Charge/degradation assumption required: " + gear.name; }
        if (n.contains("amulet of the damned") || n.contains("inquisitor") || n.contains("berserker necklace") || n.startsWith("obsidian ")) { return "Conditional effect not modeled: " + gear.name; }
        return null;
    }
    public static List<Mode> modes(OwnedGearPlanner.Gear weapon, String requested)
    {
        if (weapon == null) { return List.of(); }
        if (requested.equals("Magic")) { return List.of(new Mode("Magic", "Spell")); }
        if (requested.equals("Ranged"))
        {
            return List.of(new Mode("Ranged", "Rapid"), new Mode("Ranged", "Accurate"));
        }
        List<Mode> result = new ArrayList<>();
        for (WeaponStances.Stance stance : WeaponStances.forCategory(weapon.category))
        {
            if (!List.of("stab", "slash", "crush").contains(stance.type)) { continue; }
            String type = Character.toUpperCase(stance.type.charAt(0)) + stance.type.substring(1);
