            if (weapon.category.equals("Bow")) { return n.matches("(oak |willow |maple |yew |magic )?(shortbow|longbow)( \\(i\\))?") || n.startsWith("bow of faerdhinen") || n.startsWith("crystal bow") || n.equals("3rd age bow"); }
