        OwnedGearPlanner.Draft blocked = OwnedGearPlanner.shortlist(List.of(scim), "Melee", "Unknown", TaskReferenceData.Location.UNKNOWN, TaskReferenceData.Exemption.UNKNOWN, new AccountContext(levels, quests));
