            Map.of(ItemID.SLAYER_BAG_OF_SALT, 2L, ItemID._1DOSEPRAYERRESTORE, 3L), Map.of(ItemID.SLAYER_RING_1, 1L));
        require(TripPlanning.count(snapshot, ItemID.SLAYER_BAG_OF_SALT) == 9, "Coherent containers sum exactly once");
